const upsertWorkspaceShare = `-- name: UpsertWorkspaceShare :one
INSERT INTO workspace_shares (workspace_id, owner_user_id, grantee_user_id, level)
VALUES (
    $1::uuid,
    $2::bigint,
    $3::bigint,
    $4::varchar
)
ON CONFLICT (workspace_id, grantee_user_id)
DO UPDATE SET level = EXCLUDED.level
RETURNING id, workspace_id, owner_user_id, grantee_user_id, level, created_at
`

type UpsertWorkspaceShareParams struct {
	WorkspaceID   string `json:"workspace_id"`
	OwnerUserID   int64  `json:"owner_user_id"`
	GranteeUserID int64  `json:"grantee_user_id"`
	Level         string `json:"level"`
}

// Grants (or updates the level of) a workspace share so a grantee passes
// requireWorkspaceAccess on a shared workspace. Idempotent on
// (workspace_id, grantee_user_id) — re-granting only adjusts the level, which is
// how persisted read/write grants track member roles.
func (q *Queries) UpsertWorkspaceShare(ctx context.Context, arg UpsertWorkspaceShareParams) (WorkspaceShare, error) {
	row := q.db.QueryRow(ctx, upsertWorkspaceShare,
		arg.WorkspaceID,
		arg.OwnerUserID,
		arg.GranteeUserID,
		arg.Level,
	)
	var i WorkspaceShare
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.OwnerUserID,
		&i.GranteeUserID,
		&i.Level,
		&i.CreatedAt,
	)
	return i, err
}

const upsertWorkspaceWorkflowDefinition = `-- name: UpsertWorkspaceWorkflowDefinition :one


INSERT INTO workflow_definitions (repository_id, name, path, config)
VALUES ($1, 'Workspace', '.smithers/workspace', '{"workspace": true}'::jsonb)
ON CONFLICT (repository_id, path) DO UPDATE SET updated_at = NOW()
RETURNING id, repository_id, name, path, config, is_active, created_at, updated_at
`

// ---- Workflow Integration ----
// Creates or returns the per-repo workspace workflow definition.
// Uses the UNIQUE(repository_id, path) constraint for idempotent upserts.
func (q *Queries) UpsertWorkspaceWorkflowDefinition(ctx context.Context, repositoryID int64) (WorkflowDefinition, error) {
	row := q.db.QueryRow(ctx, upsertWorkspaceWorkflowDefinition, repositoryID)
	var i WorkflowDefinition
	err := row.Scan(
		&i.ID,
		&i.RepositoryID,
		&i.Name,
		&i.Path,
		&i.Config,
		&i.IsActive,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
